def badge(warrior):
    total = sum(warrior['stats'].values())
    top = max(warrior['stats'], key=warrior['stats'].get)
    return f"[{warrior['name']}] 综合{total} 强项{top}"

w = {'name': 'Judy', 'stats': {'atk': 30, 'def': 22, 'hack': 41}}
print(badge(w))
